</script><script>
document.addEventListener("DOMContentLoaded", () => {
  const palavrasComuns = new Set([
    "A", "O", "E", "Em", "No", "Na", "De", "Do", "Da", "Dos", "Das", "Com", "Para", "Por", "Se", "Já", "Os", "As", "Entre", "Sobre", "Quando", "Qual", "Como", "Onde", "Essa", "Esse", "Esta", "Este", "São", "Foi", "Era", "Eram", "Nos", "Nas", "Ao", "Até", "Dentre", "Ainda", "Mesmo", "Mais", "Muito", "Muitos", "Fogo", "Rio", "Sul", "Grande", "Liga", "Rei", "Manual"
  ]);

  const corrigirTexto = (texto) => {
    let corrigido = texto
      .replace(/\s+(?:35\s*:|MTG\s*:|MTG\s*50\s*anos|Regulamento Geral|Cevando o Mate|aspectos do folclore|o espaço Rio|coletânea tradicionalista|manual do tradicionalismo|origem da semana farroupilha|ABC do tradicionalismo|o folclore da mulher).*$/i, "")
      .replace(/\s*\(\s*p[áa]?(?:gina|g)?\.?\s*[\d\s,.;-]+\)\s*$/i, "");
    for (let tentativa = 0; tentativa < 3; tentativa += 1) {
      corrigido = corrigido.replace(/\b([A-ZÁÉÍÓÚÇ][a-záéíóúç]{0,5})\s+([a-záéíóúç]{1,10})\b/g, (trecho, inicio, fim) => {
        return palavrasComuns.has(inicio) ? trecho : `${inicio}${fim}`;
      });
    }
    return corrigido
      .replace(/Rio Grandedo Sul/gi, "Rio Grande do Sul")
      .replace(/Nossoacervo/gi, "Nosso acervo")
      .replace(/Foramíndios/gi, "Foram índios")
      .replace(/nov amente/gi, "novamente")
      .replace(/\s+([,.;:!?])/g, "$1")
      .replace(/\s{2,}/g, " ")
      .trim();
  };

  document.querySelectorAll("#questoes-do-pdf .banco-lista li").forEach((questao) => {
    const enunciado = questao.querySelector(":scope > span");
    if (enunciado) enunciado.textContent = corrigirTexto(enunciado.textContent);

    questao.querySelectorAll("label").forEach((alternativa) => {
      const radio = alternativa.querySelector("input");
      const texto = corrigirTexto(alternativa.textContent);
      if (!radio) return;
      alternativa.replaceChildren(radio, document.createTextNode(` ${texto}`));
    });
  });
});
</script></body>
</html>
